  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    n = len(nodes)
    if n == 0:
        raise ValueError('No nodes')
    # Build edges with mutual reachability
    edges = []
    for u, v, d in distances:
        if u not in core or v not in core:
            raise ValueError('Node missing core distance')
        w = max(core[u], core[v], d)
        # canonical order: smaller string first
        if u > v:
            u, v = v, u
        edges.append((w, u, v))
    # Sort by weight, then u, then v (deterministic tie-breaking)
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    # Union-Find (Disjoint Set Union)
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total = 0.0
    selected = 0
    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total += w
            selected += 1
            if selected == n - 1:
                break
    if selected != n - 1:
        raise ValueError('Graph is disconnected; cannot form MST')
    return {'mst_edges': mst_edges, 'total_weight': total}
